package dev.votex.addons;

import com.google.gson.*;
import java.net.URI;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.*;

/** Pure official-API parsing and policy. No keys, networking or Minecraft classes. */
public final class CurseForgeRules {
 public static final String API="https://api.curseforge.com/v1/";
 public static final int GAME=432;
 private CurseForgeRules(){}
 public record Project(long id,String name,String summary,String kind,String icon,int downloads,Boolean distributionAllowed,String website){}
 public record File(long id,long project,String name,String display,long size,String sha1,String url,Set<Long> required,Set<Long> incompatible){}
 public record Search(List<Project> projects,int total,int offset){}
 public static long id(String value){try{long number=Long.parseLong(value);if(number<1||number>0xffffffffL)throw new IllegalArgumentException();return number;}catch(RuntimeException error){throw new IllegalArgumentException("Ungültige CurseForge-Kennung");}}
 public static boolean validKey(String key){return key!=null&&key.length()>=10&&key.length()<=512&&key.chars().allMatch(c->c>=33&&c<=126);}
 public static int classId(String kind){return switch(kind){case "mod"->6;case "resourcepack"->12;case "shader"->6552;default->throw new IllegalArgumentException("Nicht unterstützter CurseForge-Inhalt");};}
 public static String kind(int classId){return switch(classId){case 6->"mod";case 12->"resourcepack";case 6552->"shader";default->throw new IllegalArgumentException("Nicht unterstützte CurseForge-Projektklasse");};}
 public static String searchRoute(String query,String kind,int offset,int limit){if(query==null||query.length()>100)throw new IllegalArgumentException("Ungültige CurseForge-Suche");int start=Math.clamp(offset,0,9999),page=Math.min(Math.clamp(limit,1,20),10000-start);return "mods/search?gameId=432&classId="+classId(kind)+"&gameVersion=26.2"+(kind.equals("mod")?"&modLoaderType=4":"")+"&searchFilter="+encode(query.strip())+"&sortField=2&sortOrder=desc&index="+start+"&pageSize="+page;}
 public static String filesRoute(long project,String kind){id(Long.toString(project));classId(kind);return "mods/"+project+"/files?gameVersion=26.2"+(kind.equals("mod")?"&modLoaderType=4":"")+"&pageSize=50&index=0";}
 public static URI api(String route){if(route==null||route.length()>1800||route.contains("#")||route.contains("\\")||!route.matches("mods/(?:search(?:\\?[A-Za-z0-9%_+&=.,~*-]*)?|[0-9]{1,10}(?:/files(?:/[0-9]{1,10}(?:/download-url)?)?(?:\\?[A-Za-z0-9%_+&=.,~*-]*)?)?)"))throw new IllegalArgumentException("Nicht unterstützter CurseForge-Endpunkt");return URI.create(API+route);}
 public static URI download(String value){URI uri=secure(value);if(!Set.of("edge.forgecdn.net","mediafilez.forgecdn.net","mediafiles.forgecdn.net").contains(uri.getHost())||uri.getQuery()!=null||!uri.getPath().matches("/files/[0-9]{1,10}/[0-9]{1,10}/[^/]+"))throw new IllegalArgumentException("Download nur von offiziellen CurseForge-Dateiquellen erlaubt");String name=uri.getPath().substring(uri.getPath().lastIndexOf('/')+1);AddonRules.filename(name);return uri;}
 public static URI icon(String value){URI uri=secure(value);if(!uri.getHost().equals("media.forgecdn.net")||!uri.getPath().startsWith("/avatars/")||uri.getQuery()!=null||uri.getPath().contains(".."))throw new IllegalArgumentException("Ungültige CurseForge-Bildquelle");return uri;}
 private static URI secure(String value){URI uri=URI.create(value);if(!"https".equals(uri.getScheme())||uri.getHost()==null||uri.getUserInfo()!=null||uri.getPort()!=-1||uri.getFragment()!=null)throw new IllegalArgumentException("Unsichere CurseForge-Quelle");return uri;}
 public static Search search(JsonObject body,String expectedKind,int offset){var data=array(body,"data");if(data.size()>50)throw new IllegalArgumentException("Zu viele CurseForge-Ergebnisse");var result=new ArrayList<Project>();for(var raw:data){var p=project(raw.getAsJsonObject());if(!p.kind().equals(expectedKind))throw new IllegalArgumentException("Falsche CurseForge-Projektklasse in Suchergebnis");result.add(p);}var pagination=body.getAsJsonObject("pagination");int total=Math.min(10000,integer(pagination,"totalCount",0,Integer.MAX_VALUE));return new Search(List.copyOf(result),total,offset);}
 public static Project project(JsonObject raw){long number=number(raw,"id",1,0xffffffffL);if(number(raw,"gameId",0,0xffffffffL)!=GAME)throw new IllegalArgumentException("CurseForge-Projekt gehört nicht zu Minecraft Java");String type=kind(integer(raw,"classId",0,Integer.MAX_VALUE));Boolean allowed=raw.has("allowModDistribution")&&!raw.get("allowModDistribution").isJsonNull()?raw.get("allowModDistribution").getAsBoolean():null;String logo="";if(raw.has("logo")&&raw.get("logo").isJsonObject())logo=text(raw.getAsJsonObject("logo"),"thumbnailUrl","",2048);String website="https://www.curseforge.com/minecraft/"+switch(type){case "mod"->"mc-mods";case "shader"->"shaders";default->"texture-packs";}+"/"+number;if(raw.has("links")&&raw.get("links").isJsonObject()){String provided=text(raw.getAsJsonObject("links"),"websiteUrl","",2048);if(!provided.isEmpty()){var uri=secure(provided);if(!uri.getHost().equals("www.curseforge.com")||!uri.getPath().startsWith("/minecraft/"))throw new IllegalArgumentException("Ungültige CurseForge-Projektseite");website=provided;}}return new Project(number,text(raw,"name","CurseForge",180),text(raw,"summary","",2000),type,logo,(int)Math.min(Integer.MAX_VALUE,number(raw,"downloadCount",0,Long.MAX_VALUE)),allowed,website);}
 public static void distribution(Project project){if(Boolean.FALSE.equals(project.distributionAllowed()))throw new IllegalArgumentException("DISTRIBUTION_RESTRICTED: Der Autor erlaubt keinen Drittanbieter-Download. Verwende seine offizielle Projektseite und anschließend den lokalen Import.");}
 public static File select(JsonObject body,Project project){distribution(project);if(array(body,"data").size()>50)throw new IllegalArgumentException("Zu viele CurseForge-Dateien");var compatible=new ArrayList<JsonObject>();for(var raw:array(body,"data")){var file=raw.getAsJsonObject();if(compatible(file,project))compatible.add(file);}compatible.sort(Comparator.<JsonObject>comparingInt(f->integer(f,"releaseType",1,3)).thenComparing((JsonObject f)->timestamp(text(f,"fileDate","",64)),Comparator.reverseOrder()).thenComparing((JsonObject f)->number(f,"id",1,0xffffffffL),Comparator.reverseOrder()));if(compatible.isEmpty())throw new IllegalArgumentException("Keine kompatible CurseForge-Datei für Minecraft 26.2 / Fabric gefunden");return file(compatible.getFirst(),project);}
 public static boolean compatible(JsonObject file,Project project){if(number(file,"modId",1,0xffffffffL)!=project.id()||number(file,"gameId",0,0xffffffffL)!=GAME)return false;if(!bool(file,"isAvailable",false)||bool(file,"isServerPack",false)||bool(file,"isEarlyAccessContent",false))return false;boolean game=false,fabric=false,iris=false,optifine=false;for(var raw:array(file,"gameVersions")){String value=raw.getAsString();game|=value.equals("26.2");fabric|=value.equalsIgnoreCase("Fabric");iris|=value.equalsIgnoreCase("Iris");optifine|=value.equalsIgnoreCase("OptiFine");}return game&&(!project.kind().equals("mod")||fabric)&&(!project.kind().equals("shader")||!optifine||iris);}
 public static File file(JsonObject raw,Project project){distribution(project);if(!compatible(raw,project))throw new IllegalArgumentException("Inkompatible oder nicht verfügbare CurseForge-Datei");long fileId=number(raw,"id",1,0xffffffffL),size=number(raw,"fileLength",1,AddonRules.MAX_FILE);String filename=AddonRules.filename(text(raw,"fileName","",180));if(!filename.endsWith(project.kind().equals("mod")?".jar":".zip"))throw new IllegalArgumentException("Falsches CurseForge-Dateiformat");String sha1="";for(var h:array(raw,"hashes")){var hash=h.getAsJsonObject();if(integer(hash,"algo",1,2)==1)sha1=text(hash,"value","",40);}if(!sha1.matches("[A-Fa-f0-9]{40}"))throw new IllegalArgumentException("CurseForge-Datei enthält keine gültige SHA-1-Prüfsumme");String url=text(raw,"downloadUrl","",4096);if(!url.isEmpty())download(url);var required=new LinkedHashSet<Long>();var incompatible=new LinkedHashSet<Long>();for(var dependency:array(raw,"dependencies")){var d=dependency.getAsJsonObject();int relation=integer(d,"relationType",1,6);if(relation==3)required.add(number(d,"modId",1,0xffffffffL));else if(relation==5)incompatible.add(number(d,"modId",1,0xffffffffL));}if(required.size()>40||incompatible.size()>100)throw new IllegalArgumentException("Zu viele CurseForge-Abhängigkeiten");return new File(fileId,project.id(),filename,text(raw,"displayName",filename,200),size,sha1.toLowerCase(Locale.ROOT),url,Set.copyOf(required),Set.copyOf(incompatible));}
 public static void verify(File file,byte[] bytes){if(bytes==null||bytes.length!=file.size()||bytes.length>AddonRules.MAX_FILE)throw new IllegalArgumentException("CurseForge-Dateigröße stimmt nicht überein");try{String actual=HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-1").digest(bytes));if(!actual.equals(file.sha1()))throw new IllegalArgumentException("CurseForge-Download-Prüfsumme stimmt nicht überein");}catch(java.security.NoSuchAlgorithmException error){throw new IllegalStateException(error);}}
 private static Instant timestamp(String value){try{return Instant.parse(value);}catch(Exception ignored){return Instant.EPOCH;}}
 private static String encode(String value){return URLEncoder.encode(value,StandardCharsets.UTF_8);}
 private static JsonArray array(JsonObject o,String key){var value=o.get(key);if(value==null||!value.isJsonArray())throw new IllegalArgumentException("CurseForge-Antwort enthält keine gültige Liste: "+key);return value.getAsJsonArray();}
 private static String text(JsonObject o,String key,String fallback,int max){var value=o.get(key);String result=value==null||value.isJsonNull()?fallback:value.getAsString();if(result.length()>max)throw new IllegalArgumentException("CurseForge-Textfeld überschreitet das Limit");return result;}
 private static boolean bool(JsonObject o,String key,boolean fallback){var value=o.get(key);return value==null||value.isJsonNull()?fallback:value.getAsBoolean();}
 private static int integer(JsonObject o,String key,int min,int max){return (int)number(o,key,min,max);}
 private static long number(JsonObject o,String key,long min,long max){var value=o.get(key);if(value==null||value.isJsonNull())throw new IllegalArgumentException("CurseForge-Zahlenfeld fehlt: "+key);long result;try{result=value.getAsBigDecimal().longValueExact();}catch(RuntimeException error){throw new IllegalArgumentException("Ungültige CurseForge-Zahl: "+key);}if(result<min||result>max)throw new IllegalArgumentException("CurseForge-Zahl außerhalb des Bereichs: "+key);return result;}
}
